package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Any problem (missing file, missing or malformed value, unknown key) is reported through a
 * {@link ConfigException} listing every problem found; nothing silently falls back to a default.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");
    private static final Set<String> KNOWN_KEYS = Set.of(
            "upstream.url",
            "api.token",
            "worker.threads",
            "queue.capacity",
            "retry.max-attempts",
            "request.timeout",
            "metrics.enabled");

    private final Properties properties;
    private final List<String> problems = new ArrayList<>();

    private ConfigLoader(Properties properties) {
        this.properties = properties;
    }

    public static ServiceConfig load(Path file) {
        ConfigLoader loader = new ConfigLoader(read(file));
        ServiceConfig config = loader.parse();
        if (!loader.problems.isEmpty()) {
            throw new ConfigException(
                    "Invalid configuration in " + file + ":\n  - " + String.join("\n  - ", loader.problems));
        }
        return config;
    }

    private ServiceConfig parse() {
        reportUnknownKeys();
        return new ServiceConfig(
                uri("upstream.url"),
                required("api.token"),
                intValue("worker.threads", DEFAULT_WORKER_THREADS, 1),
                intValue("queue.capacity", DEFAULT_QUEUE_CAPACITY, 1),
                intValue("retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0),
                duration("request.timeout"),
                bool("metrics.enabled"));
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("Cannot read configuration file " + file + ": " + e);
        }
        return properties;
    }

    private void reportUnknownKeys() {
        Set<String> unknown = new TreeSet<>(properties.stringPropertyNames());
        unknown.removeAll(KNOWN_KEYS);
        for (String key : unknown) {
            problems.add("unknown key '" + key + "' (known keys: " + new TreeSet<>(KNOWN_KEYS) + ")");
        }
    }

    private String required(String key) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            problems.add(key + " is required");
            return null;
        }
        return value.trim();
    }

    private URI uri(String key) {
        String raw = required(key);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            String scheme = uri.getScheme();
            if (!"http".equalsIgnoreCase(scheme) && !"https".equalsIgnoreCase(scheme) || uri.getHost() == null) {
                problems.add(key + " must be an http(s) URL with a host, but was '" + raw + "'");
                return null;
            }
            return uri;
        } catch (Exception e) {
            problems.add(key + " is not a valid URL: '" + raw + "'");
            return null;
        }
    }

    private int intValue(String key, int defaultValue, int minimum) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        try {
            int value = Integer.parseInt(raw.trim());
            if (value < minimum) {
                problems.add(key + " must be at least " + minimum + ", but was " + value);
            }
            return value;
        } catch (NumberFormatException e) {
            problems.add(key + " must be a whole number, but was '" + raw.trim() + "'");
            return defaultValue;
        }
    }

    private Duration duration(String key) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        Matcher matcher = DURATION.matcher(raw.trim());
        if (!matcher.matches()) {
            problems.add(key + " must be a number followed by ms, s or m (e.g. 30s), but was '" + raw.trim() + "'");
            return DEFAULT_REQUEST_TIMEOUT;
        }
        try {
            long amount = Long.parseLong(matcher.group(1));
            return switch (matcher.group(2)) {
                case "ms" -> Duration.ofMillis(amount);
                case "s" -> Duration.ofSeconds(amount);
                default -> Duration.ofMinutes(amount);
            };
        } catch (ArithmeticException | NumberFormatException e) {
            problems.add(key + " is out of range: '" + raw.trim() + "'");
            return DEFAULT_REQUEST_TIMEOUT;
        }
    }

    private boolean bool(String key) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return false;
        }
        String value = raw.trim();
        if (value.equals("true") || value.equals("false")) {
            return Boolean.parseBoolean(value);
        }
        problems.add(key + " must be 'true' or 'false', but was '" + value + "'");
        return false;
    }
}

