            problems.add(key + " is not a valid URL: '" + raw + "'");
            return null;
        }
    }

    private int intValue(String key, int defaultValue, int minimum) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        try {
            int value = Integer.parseInt(raw.trim());
            if (value < minimum) {
                problems.add(key + " must be at least " + minimum + ", but was " + value);
            }
            return value;
        } catch (NumberFormatException e) {
            problems.add(key + " must be a whole number, but was '" + raw.trim() + "'");
            return defaultValue;
        }
    }

    private Duration duration(String key) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        Matcher matcher = DURATION.matcher(raw.trim());
        if (!matcher.matches()) {
            problems.add(key + " must be a number followed by ms, s or m (e.g. 30s), but was '" + raw.trim() + "'");
            return DEFAULT_REQUEST_TIMEOUT;
        }
        try {
            long amount = Long.parseLong(matcher.group(1));
            return switch (matcher.group(2)) {
                case "ms" -> Duration.ofMillis(amount);
                case "s" -> Duration.ofSeconds(amount);
                default -> Duration.ofMinutes(amount);
            };
        } catch (ArithmeticException | NumberFormatException e) {
            problems.add(key + " is out of range: '" + raw.trim() + "'");
            return DEFAULT_REQUEST_TIMEOUT;
        }
    }

    private boolean bool(String key) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return false;
        }
        String value = raw.trim();
        if (value.equals("true") || value.equals("false")) {
            return Boolean.parseBoolean(value);
        }
        problems.add(key + " must be 'true' or 'false', but was '" + value + "'");
        return false;
    }
